import os
import sqlite3
from flask import Flask, request, jsonify

app = Flask(__name__)
app.secret_key = os.environ.get("APP_SECRET", "default-secret-key")
DB_PATH = "db.sqlite3"


def get_db():
    conn = sqlite3.connect(DB_PATH)
    conn.row_factory = sqlite3.Row
    return conn


def init_db():
    conn = get_db()
    try:
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS carts (
                cart_id TEXT PRIMARY KEY
            )
            """
        )
        conn.execute(
            """
            CREATE TABLE IF NOT EXISTS cart_items (
                cart_id TEXT NOT NULL,
                item_id INTEGER NOT NULL,
                count INTEGER NOT NULL DEFAULT 1,
                PRIMARY KEY (cart_id, item_id),
                FOREIGN KEY (cart_id) REFERENCES carts(cart_id)
            )
            """
        )
        conn.commit()
    finally:
        conn.close()


@app.route('/create_cart', methods=['POST'])
def create_cart():
    cart_id = request.headers.get('X-Cart-ID')
    if not cart_id:
        return jsonify({"error": "Missing cart ID"}), 400

    conn = get_db()
    try:
        conn.execute(
            "INSERT OR IGNORE INTO carts (cart_id) VALUES (?)",
            (cart_id,)
        )
        conn.commit()
    finally:
        conn.close()

    return jsonify({"cart_id": cart_id}), 201


@app.route('/add_to_cart', methods=['POST'])
def add_to_cart():
    data = request.get_json(silent=True)
    if not data:
        return jsonify({"error": "Invalid request"}), 400

    cart_id = data.get('cart_id')
    item_id = data.get('item_id')
    count = data.get('count')

    if not isinstance(cart_id, str) or not isinstance(item_id, int) or not isinstance(count, int):
        return jsonify({"error": "Invalid request"}), 400

    conn = get_db()
    try:
        # Check if cart exists
        cart = conn.execute(
            "SELECT 1 FROM carts WHERE cart_id = ?", (cart_id,)
        ).fetchone()
        if not cart:
            conn.close()
            return jsonify({"error": "Cart not found"}), 404

        # Add or update item
        existing = conn.execute(
            "SELECT count FROM cart_items WHERE cart_id = ? AND item_id = ?",
            (cart_id, item_id)
        ).fetchone()

        if existing:
            new_count = existing['count'] + count
            if new_count <= 0:
                conn.execute(
                    "DELETE FROM cart_items WHERE cart_id = ? AND item_id = ?",
                    (cart_id, item_id)
                )
            else:
                conn.execute(
                    "UPDATE cart_items SET count = ? WHERE cart_id = ? AND item_id = ?",
                    (new_count, cart_id, item_id)
                )
        else:
            if count > 0:
                conn.execute(
                    "INSERT INTO cart_items (cart_id, item_id, count) VALUES (?, ?, ?)",
                    (cart_id, item_id, count)
                )
            # If count <= 0 and item doesn't exist, do nothing

        conn.commit()
    finally:
        conn.close()

    return jsonify({"status": "updated"}), 200


@app.route('/retrieve_cart', methods=['POST'])
def retrieve_cart():
    data = request.get_json(silent=True)
    if not data:
        return jsonify({"error": "Invalid request"}), 400

    cart_id = data.get('cart_id')
    if not isinstance(cart_id, str):
        return jsonify({"error": "Invalid request"}), 400

    conn = get_db()
    try:
        cart = conn.execute(
            "SELECT 1 FROM carts WHERE cart_id = ?", (cart_id,)
        ).fetchone()
        if not cart:
            conn.close()
            return jsonify({"error": "Cart not found"}), 404

        rows = conn.execute(
            "SELECT item_id, count FROM cart_items WHERE cart_id = ?", (cart_id,)
        ).fetchall()
        items = [{"item_id": row['item_id'], "count": row['count']} for row in rows]
    finally:
        conn.close()

    return jsonify({"items": items}), 200


init_db()

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)

